import * as THREE from 'three';
export function bindControls({camera,controls,renderer,getClickable,views,onSelect}){let destination=null;const raycaster=new THREE.Raycaster(),mouse=new THREE.Vector2();let down=null;renderer.domElement.addEventListener('pointerdown',event=>down={x:event.clientX,y:event.clientY});renderer.domElement.addEventListener('pointerup',event=>{if(!down||Math.hypot(event.clientX-down.x,event.clientY-down.y)>7)return;const rect=renderer.domElement.getBoundingClientRect();mouse.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(mouse,camera);const hit=raycaster.intersectObjects(getClickable())[0];onSelect(hit?.object.userData||null)});const setView=name=>{destination=new THREE.Vector3(...views[name]);document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===name))};document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>setView(button.dataset.view));document.getElementById('reset').onclick=()=>setView('iso');addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});return()=>{if(destination){camera.position.lerp(destination,.08);if(camera.position.distanceTo(destination)<.04)destination=null}controls.update()}}
